/** @type {import('tailwindcss').Config} */
export default {
  content: [
    "./index.html",
    "./*.{js,jsx,ts,tsx}",
    "./components/**/*.{js,jsx,ts,tsx}",
    "./pages/**/*.{js,jsx,ts,tsx}"
  ],
  theme: {
    extend: {},
  },
  plugins: [],
}

import { mkdir } from 'fs/promises'
import { existsSync } from 'fs'
import { resolve } from 'path'

const buildDir = resolve(process.cwd(), 'build/client')

async function ensureBuildDir() {
  if (!existsSync(buildDir)) {
    await mkdir(buildDir, { recursive: true })
  }
}

ensureBuildDir()

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import { resolve } from 'path'

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [react()],
  build: {
    outDir: 'build/client',
    emptyOutDir: true,
    rollupOptions: {
      input: {
        main: resolve(__dirname, 'index.html'),
      },
    },
  },
})

import os
import json
from pathlib import Path

def should_skip_dir(dir_name):
    skip_dirs = {'node_modules', 'build', '__pycache__', '.git'}
    return dir_name in skip_dirs

def read_file_content(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            return f.read()
    except Exception as e:
        return f"Error reading file: {str(e)}"

def export_files_to_json():
    root_dir = Path('.')
    result = []

    for path in root_dir.rglob('*'):
        if path.is_file() and not should_skip_dir(path.parts[0]):
            relative_path = str(path.relative_to(root_dir))
            content = read_file_content(path)

            result.append({
                "path": relative_path,
                "content": content
            })

    # Write to JSON file
    with open('files_export.json', 'w', encoding='utf-8') as f:
        json.dump(result, f, indent=2, ensure_ascii=False)

    print(f"Exported {len(result)} files to files_export.json")

if __name__ == "__main__":
    export_files_to_json()

